const nav=document.querySelector('.nav');const toggle=document.querySelector('.menu-toggle');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('menu-open');toggle.setAttribute('aria-expanded',String(open));});document.querySelectorAll('nav a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');}));